// Sparse per-file edits: no audio decoding, analysis or complete-loop save needed.
struct ParameterBatch{std::map<juce::String,juce::var> before,after;std::map<juce::String,juce::String> baselineLoops,baselineNative;juce::String activePath,beforeXml,afterXml;uint64_t generation=0;uint64_t order=nextHistoryOrder();};
std::vector<ParameterBatch> parameterUndo,parameterRedo;std::atomic<int> parameterBusy{0};std::atomic<int> parameterChanged{0};std::atomic<uint64_t> parameterCompleted{0};uint64_t parameterRevisionSeen=0;std::shared_ptr<const AudioData> loadedParameterAudio;juce::String loadedParameterBaseline;
static juce::var parameterValues(const juce::File& file){return LibraryStore::read("parameter-edits.json").getProperty(file.getFullPathName(),{});}
static bool writeParameterValues(const std::map<juce::String,juce::var>& values){return LibraryStore::update("parameter-edits.json",[&](juce::DynamicObject& object){for(auto& pair:values){if(pair.second.isVoid())object.removeProperty(pair.first);else object.setProperty(pair.first,pair.second);}});}
bool queueParameterEdit(const juce::Array<juce::File>& files,const juce::String& field,double value){if(!allowedParameter(field)||!std::isfinite(value))return false;queueAutoSave(true);++parameterBusy;autoSavePool.addJob([this,files,field,value]{ParameterBatch batch;{const juce::ScopedLock g(lock);if(audio&&files.contains(juce::File(audio->path))){batch.activePath=audio->path;batch.generation=loadGeneration;batch.beforeXml=configurationXml()->toString();}}auto all=LibraryStore::read("parameter-edits.json");for(auto file:files){if(!LibraryStore::editable(file)||file.isDirectory()||file.hasFileExtension("mid;midi;sgpreset"))continue;auto path=file.getFullPathName();if(file.hasFileExtension("sgmulti"))batch.baselineNative[path]=file.loadFileAsString();else if(LibraryStore::playbackType(file)==6){auto local=LocalMultiEdits::location(file);batch.baselineNative[local.getFullPathName()]=local.existsAsFile()?local.loadFileAsString():juce::String();}auto baseline=LibraryStore::database()->loop(path);batch.baselineLoops[path]=baseline;if(auto xml=juce::parseXML(baseline)){auto hash=xml->getStringAttribute("contentHash");if(hash.isNotEmpty())batch.baselineLoops["sha256:"+hash]=LibraryStore::database()->loop("sha256:"+hash);}auto old=all.getProperty(path,{});auto next=old.clone();if(!next.isObject())next=juce::var(new juce::DynamicObject());next.getDynamicObject()->setProperty(field,value);if(field=="swingAmount")next.getDynamicObject()->setProperty("swing",1);if(field=="strength")next.getDynamicObject()->setProperty("sliceMethod",1);if(field=="divisions")next.getDynamicObject()->setProperty("sliceMethod",0);if(field=="bulkBars")next.getDynamicObject()->removeProperty("bulkResizeBars");if(field=="bulkResizeBars")next.getDynamicObject()->removeProperty("bulkBars");batch.before[path]=old;batch.after[path]=next;}bool ok=!batch.after.empty()&&writeParameterValues(batch.after);{const juce::ScopedLock g(lock);if(ok){if(audio&&audio->path==batch.activePath&&loadGeneration==batch.generation){auto patch=juce::var(new juce::DynamicObject());patch.getDynamicObject()->setProperty(field,value);if(field=="swingAmount")patch.getDynamicObject()->setProperty("swing",1);if(field=="strength")patch.getDynamicObject()->setProperty("sliceMethod",1);if(field=="divisions")patch.getDynamicObject()->setProperty("sliceMethod",0);applyParameterValues(patch);batch.afterXml=configurationXml()->toString();libraryDirty=false;serviceTrack();}parameterChanged=(int)batch.after.size();parameterUndo.push_back(std::move(batch));if(parameterUndo.size()>64)parameterUndo.erase(parameterUndo.begin());parameterRedo.clear();}}if(!ok)parameterChanged=0;++parameterCompleted;--parameterBusy;});return true;}
uint64_t nextParameterOrder(bool redo){const juce::ScopedLock g(lock);auto& stack=redo?parameterRedo:parameterUndo;return parameterBusy||stack.empty()?0:stack.back().order;}
bool undoParameters(bool redo){if(parameterBusy.load())return false;++parameterBusy;ParameterBatch batch;{const juce::ScopedLock g(lock);auto& stack=redo?parameterRedo:parameterUndo;if(stack.empty()){--parameterBusy;return false;}batch=stack.back();}autoSavePool.addJob([this,redo,batch]{bool ok=writeParameterValues(redo?batch.after:batch.before);if(ok&&!redo){auto restore=batch.baselineLoops;for(auto& pair:batch.before)if(auto current=juce::parseXML(LibraryStore::database()->loop(pair.first))){auto hash=current->getStringAttribute("contentHash");auto key="sha256:"+hash;if(hash.isNotEmpty()&&!restore.count(key)&&current->getStringAttribute("file")==pair.first)restore[key]={};}for(auto& item:batch.baselineNative){juce::File file(item.first);if(LibraryStore::editable(file)&&(!file.hasFileExtension("sgmulti")||file.existsAsFile())){if(item.second.isEmpty()){if(file.existsAsFile())ok=file.deleteFile()&&ok;}else{file.getParentDirectory().createDirectory();juce::TemporaryFile temporary(file);ok=temporary.getFile().replaceWithText(item.second)&&temporary.overwriteTargetFileWithTemporary()&&ok;}}}ok=LibraryStore::database()->restoreLoopEntries(restore)&&ok;LibraryStore::pollDatabase();LibraryStore::notifySharing();}{const juce::ScopedLock g(lock);if(ok){if(audio&&batch.before.count(audio->path)){auto text=audio->path==batch.activePath?(redo?batch.afterXml:batch.beforeXml):(audio==loadedParameterAudio?loadedParameterBaseline:juce::String());auto xml=juce::parseXML(text);if(xml){++historySuppressed;applyConfiguration(*xml,false);if(audio->path!=batch.activePath){auto& values=redo?batch.after:batch.before;applyParameterValues(values.at(audio->path));}--historySuppressed;libraryDirty=false;serviceTrack();}}auto& from=redo?parameterRedo:parameterUndo;auto& to=redo?parameterUndo:parameterRedo;from.pop_back();to.push_back(batch);}}++parameterCompleted;--parameterBusy;});return true;}
static bool allowedParameter(juce::String key){static const std::set<juce::String> fields{"pitch","keyLocked","targetKey","bulkBpm","bulkBars","bulkResizeBars","lateWindow","grid","gridSliceSwing","quantizeEarly","boundarySnap","divisions","bulkSliceGain","bulkSliceEnv","bulkSliceAttack","bulkSliceHold","bulkSliceDecay","bulkSliceEnd","bulkSliceFade","gridSnapMode","sliceMethod","strength","quantize","quantizeAmount","swing","swingAmount","shotOctaveShift","shotGainDb","shotMono","shotLegato","shotAttack","shotDecay","shotSustain","shotRelease","shotVelocity","shotBendRange","shotLoop","shotPingPong","shotExitLoop","shotZeroSnap","shotCrossfadeMs","shotLoopFade","shotFilterFade","shotLoopTravel","shotFilterCutoff"};return fields.count(key)!=0;}
void applyParameterValues(const juce::var& values){auto* object=values.getDynamicObject();if(!audio||!object)return;auto config=configurationXml();for(auto& pair:object->getProperties()){auto key=pair.name.toString();if(!allowedParameter(key))continue;if(key!="bulkBpm"&&key!="bulkBars"&&key!="bulkResizeBars"&&key!="bulkSliceEnd"&&key!="bulkSliceFade")config->setAttribute(key,pair.value.toString());}++historySuppressed;applyConfiguration(*config,false);if(object->hasProperty("bulkBpm")){double bpm=(double)object->getProperty("bulkBpm");if(trackMode)applyTrackParameterTempo(bpm);else setSourceBpm(bpm);}if(object->hasProperty("bulkBars")&&!oneShotMode&&!trackMode)setRegionBars((double)object->getProperty("bulkBars"));if(object->hasProperty("bulkResizeBars")&&!oneShotMode&&!trackMode)setLoopBars((double)object->getProperty("bulkResizeBars"));for(auto& slice:slices){if(object->hasProperty("bulkSliceEnd")){slice.playbackLengthMs=(double)object->getProperty("bulkSliceEnd");if(slice.playbackLengthMs<0)slice.playbackEnd=1;}if(object->hasProperty("bulkSliceFade"))slice.endFadeMs=(double)object->getProperty("bulkSliceFade");if(object->hasProperty("bulkSliceGain"))slice.gainDb=juce::jlimit(-60.,24.,(double)object->getProperty("bulkSliceGain"));if(object->hasProperty("bulkSliceEnv"))slice.envelope.enabled=(bool)object->getProperty("bulkSliceEnv");if(object->hasProperty("bulkSliceAttack"))slice.envelope.attack=juce::jlimit(0.,5000.,(double)object->getProperty("bulkSliceAttack"));if(object->hasProperty("bulkSliceHold"))slice.envelope.hold=juce::jlimit(0.,5000.,(double)object->getProperty("bulkSliceHold"));if(object->hasProperty("bulkSliceDecay"))slice.envelope.decay=juce::jlimit(0.,10000.,(double)object->getProperty("bulkSliceDecay"));}if(!oneShotMode&&!stretchMode&&!trackMode&&(object->hasProperty("sliceMethod")||object->hasProperty("strength")||(object->hasProperty("gridSliceSwing")&&sliceMethod==0))){int method=object->hasProperty("sliceMethod")?(int)object->getProperty("sliceMethod"):preferredSliceMethod;if(method)detect(object->hasProperty("strength")?(double)object->getProperty("strength"):detectStrength);else split(divisions);preferredSliceMethod=method;}--historySuppressed;}

void applyTrackParameterTempo(double bpm){if(!std::isfinite(bpm))return;bpm=juce::jlimit(20.,400.,bpm);if(!trackGridReady){trackPendingParameterBpm=bpm;sourceBpm=bpm;return;}double ratio=bpm/trackGrid.bpm;trackGrid.bpm=bpm;for(auto& a:trackGrid.anchors)a.beat*=ratio;for(auto& a:trackGrid.analysed)a.beat*=ratio;for(auto& a:trackGrid.manual)a.beat*=ratio;for(auto& a:trackGrid.removed)a*=ratio;trackGrid.straightAnchor.beat*=ratio;trackGrid.beatOffset*=ratio;sourceBpm=bpm;}
